from mk import *
from lib import fbd
STRICT["on"] = True

def fig():
    g = Fig(560, 260, "קפיץ תלוי מהתקרה, ובקצהו לוח עץ אופקי במסה M. קליע במסה m נע אנכית כלפי מעלה במהירות v, חודר דרך הלוח ויוצא במהירות u")
    g.ceiling(200, 360, 20); g.spring(280, 20, 280, 130, coils=9)
    g.rect(200, 130, 160, 14, fill="var(--d-fill)"); g.text(370, 142, "M", anchor="start")
    g.line(180, 137, 380, 137, stroke="var(--d-dim)", width=1, dash="3 3")
    g.circle(280, 220, 4, fill="var(--d-label)"); g.arrow(280, 214, 280, 160, "v", lx=290, ly=190, anchor="start"); g.text(270, 236, "m", anchor="end")
    return g

E(id="bagrut-1996-q4", year=1996, label="1996 שאלה 4", topic="momentum", sub="mom-collisions", diff=4, fig=fig,
  stem=r"קפיץ קל, שקבוע הקפיץ שלו $K$, תלוי מהתקרה. לקצה התחתון שלו מחובר לוח עץ אופקי שמסתו $M$. במצב שיווי משקל הקפיץ ארוך ב-$d$ מהאורך הרפוי שלו.",
  parts=[
    P("א", r"כתבו את $d$ בעזרת $M$ ו-$K$.", choice([r"$d = \frac{Mg}{K}$", r"$d = \frac{K}{Mg}$", r"$d = \frac{2Mg}{K}$", r"$d = \sqrt{\frac{M}{K}}$"], 0), ["fbd", "principle"], [
        D(r"תרשים הכוחות על הלוח", lambda: fbd([("F_sp", 90, 0.8), ("Mg", -90, 0.8)],
            "תרשים כוחות על הלוח: כוח הקפיץ כלפי מעלה וכוח הכובד כלפי מטה. הכיוון החיובי כלפי מעלה",
            positive=90, body="block")),
        S(r"משוואת כוחות", r"בשיווי משקל התאוצה אפס. הכיוון החיובי כלפי מעלה, ולא נקבע בשאלה", r"F_{sp} - Mg = 0", eq=r"\Sigma\vec F = m\vec a"),
        S(r"מציבים את כוח הקפיץ", r"ההתארכות היא המרחק שנשאל עליו", r"K d = Mg \;\Rightarrow\; d = \frac{Mg}{K}", eq=r"F_{sp} = K\Delta\ell"),
    ], r"$d = \frac{Mg}{K}$", key=r"d = Mg/k"),
    P("ב", r"מושכים את הלוח מטה מרחק $A$ ממצב שיווי המשקל ומשחררים אותו, והוא מתנודד. ברגע שהלוח עובר בנקודת שיווי המשקל בדרכו מטה, פוגע בו קליע שמסתו $m$ ונע אנכית כלפי מעלה במהירות $v$. הקליע עובר דרך הלוח ויוצא ממנו במהירות $u$, והלוח נעצר ונשאר במנוחה בנקודת שיווי המשקל. ההתנגשות קצרה מאוד, ומסת הלוח לא משתנה. מה ההפרש בין גדלי המהירויות של הקליע, $v - u$, בעזרת $M$, $K$, $m$ ו-$A$?", choice([r"$v - u = \frac{A}{m}\sqrt{MK}$", r"$v - u = \frac{A}{m}\sqrt{\frac{K}{M}}$", r"$v - u = \frac{MA}{m}\cdot\frac{K}{M}$", r"$v - u = A\sqrt{\frac{K}{m}}$"], 0), ["principle", "algebra"], [
        S(r"מהירות הלוח בשיווי משקל", r"הלוח עושה תנודה הרמונית במשרעת שנשאלה. בנקודת שיווי המשקל המהירות שלו מרבית", r"V = \omega A = A\sqrt{\frac{K}{M}}", eq=r"v_{\max} = \omega A,\qquad \omega = \sqrt{\frac{K}{m}}"),
        S(r"שימור תנע בהתנגשות", r"ההתנגשות קצרה מאוד, ולכן אפשר להזניח את הכובד ואת כוח הקפיץ בזמנה. הכיוון החיובי כלפי מעלה. הלוח יורד לפני ההתנגשות, ואחריה הוא במנוחה", r"m v + M(-V) = m u + M \cdot 0", eq=r"m_A\vec v_A + m_B\vec v_B = m_A\vec u_A + m_B\vec u_B"),
        S(r"מבודדים", r"מציבים את מהירות הלוח", r"v - u = \frac{M V}{m} = \frac{M A}{m}\sqrt{\frac{K}{M}} = \frac{A}{m}\sqrt{MK}"),
    ], r"$v - u = \frac{A}{m}\sqrt{MK}$", key=r"v−u=(A/m)√(Mk)"),
    P("ג", r"קליע אחר, שנע אנכית כלפי מעלה, פוגע בלוח כשהלוח נמצא במרחק כלשהו מנקודת שיווי המשקל, ועובר דרכו. הסבירו למה במקרה הזה הלוח לא יכול להיעצר ולהישאר במנוחה.", OPEN, ["principle"], [
        S(r"מחוץ לשיווי המשקל", r"גם אם הלוח נעצר לרגע, הקפיץ לא מאזן שם בדיוק את הכובד. הכוח השקול לא אפס, ולכן יש ללוח תאוצה והוא ממשיך לזוז", r"x \ne 0 \;\Rightarrow\; \Sigma F = -Kx \ne 0"),
    ], r"רק בנקודת שיווי המשקל הכוח השקול אפס"),
  ],
  concepts=["שיווי משקל של קפיץ", "תנודה הרמונית", "שימור תנע", "עצירה קבועה"],
  summary=r"קליע שעובר דרך לוח שמתנודד על קפיץ ועוצר אותו: הקשר בין הפרש מהירויות הקליע למשרעת, ולמה אפשר לעצור רק בשיווי משקל.",
  review="הנחה שלי.\nבמקור כתוב שמושכים את הלוח מטה בשיעור A, והבנתי שזו המשרעת. בסעיפים א ו-ב התלמיד בוחר את הביטוי הנכון מתוך ארבעה.\nמה לבדוק: רק לאשר.")
